clap_mangen = "0.3.0"
cstr = "0.2"
cli-table = "0.5.0"
console = "0.16.3"
detect-coding-agent = "0.1.0"
dialoguer = "0.12.0"
dotenv = { package = "dotenv-ng", version = "1.0.0" }
fd-lock = "4"
futures = "0.3.32"
hex = "0.4.3"
hostname = "0.4.2"
humantime = "2"
